 const {outbreakRecipe}=await import('../outbreak-scenes.mjs'),{planSettlementPreset}=await import('../settlement-layout.js'),{syncWorld}=await import('../world-model.mjs'),{worldNavigation}=await import('../world-navigation.mjs'),{syncEncounter}=await import('../outbreak-simulation.mjs');
 const entries=sceneEntries||[{type:'zombies',preset:'stragglers',seed:41,q:0,r:0},{type:'brains',preset,seed:63,q:0,r:1}],cards=entries.map((e,index)=>({id:sceneEntries?e.type+index:e.type,type:e.type,revision:1,cells:[{q:0,r:0}],rendition:{meshes:[]},recipe:outbreakRecipe(e.type,e.preset,e.seed),capabilities:{}}));
